package com.mantou.salesdialer.contacts;
import android.Manifest;import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.util.AtomicFile;import android.widget.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.json.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.DataClass;

/** Non-exported local operator UI. Intent input can only suggest an owned opaque selection. */
public final class PilotActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView summary,notice;private Spinner targets;private final Map<String,Button> buttons=new LinkedHashMap<>();private boolean busy=true,rendering;private String selected="",message="正在读取……";private Data current;private int generation;private final String session=UUID.randomUUID().toString();
 private static final class Data {List<PhoneIntakeStore.Contact> contacts;List<PhoneIntakeStore.DraftView> drafts;List<PhoneIntakeStore.PilotAttempt> attempts;PhoneIntakeStore.PlanView plan;PilotPhoneRuntime.Account account;JSONObject report;}
 private interface Work {void run()throws Exception;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);String suggested=getIntent().getStringExtra("targetId");if(suggested!=null&&suggested.matches("LOCAL-TARGET-[a-f0-9]{32}"))selected=suggested;LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(32,32,32,32);ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);TextView title=new TextView(this);title.setTextSize(22);title.setText("受控通话与结果");body.addView(title);TextView hint=new TextView(this);hint.setText("仅为当前联系人授权一次，使用明确绑定的销售SIM。按北京时间工作日09:00至18:00执行；未接不自动重拨。\n系统接受请求、响铃、接通和人工记录分别核对。");body.addView(hint);summary=new TextView(this);body.addView(summary);targets=new Spinner(this);targets.setContentDescription("选择受控联系人");body.addView(targets);targets.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){if(!rendering&&current!=null&&n<current.contacts.size()){selected=current.contacts.get(n).id;controls();}}});
  button(body,"授予手机验证权限",()->requestPermissions(new String[]{Manifest.permission.CALL_PHONE,Manifest.permission.READ_PHONE_STATE,Manifest.permission.READ_PHONE_NUMBERS},77));
  button(body,"选择销售SIM",this::selectAccount);button(body,"允许准时提醒",()->startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName()))));button(body,"后台运行设置",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));
  button(body,"立即受控提交1次",()->confirm(false));button(body,"为当前计划授权1次定时通话",()->confirm(true));button(body,"暂停新外呼",()->submit("STOP",()->{PilotPhoneRuntime.stopAll(getApplicationContext());message="已停止新外呼；已交给电话系统的通话需在电话界面结束。";}));
  button(body,"记录人工已接通并结束",()->result("COMPLETED",false));button(body,"记录未接听",()->result("NO_ANSWER",false));button(body,"记录结果未知",()->result("UNKNOWN",false));button(body,"明确关闭未知待核对",()->result("UNKNOWN",true));button(body,"刷新通话与计划",()->submit("REFRESH",()->message="已读取当前记录。"));
  notice=new TextView(this);body.addView(notice);controls();
 }
 @Override protected void onResume(){super.onResume();if(!worker.isShutdown())submit("OPEN",()->{});}
 @Override public void onRequestPermissionsResult(int request,String[] p,int[] grants){super.onRequestPermissionsResult(request,p,grants);if(!busy)submit("PERMISSIONS",()->message="已重新检查手机权限；尚未授权通话。" );}
 private void button(LinearLayout body,String label,Runnable action){Button b=new Button(this);b.setText(label);body.addView(b);buttons.put(label,b);b.setOnClickListener(v->{if(!busy)action.run();});}
 private PhoneIntakeStore.Contact chosen(){return current==null?null:current.contacts.stream().filter(c->c.id.equals(selected)).findFirst().orElse(null);}
 private PhoneIntakeStore.DraftView draft(){return current==null?null:current.drafts.stream().filter(d->d.draft.targetId.equals(selected)).findFirst().orElse(null);}
 private PhoneIntakeStore.PilotAttempt pending(){return current==null?null:current.attempts.stream().filter(a->a.pending).findFirst().orElse(null);}
 private void controls(){for(Button b:buttons.values())b.setEnabled(!busy);targets.setEnabled(!busy&&current!=null&&!current.contacts.isEmpty());boolean selectedReady=!busy&&chosen()!=null&&draft()!=null&&current.account!=null&&pending()==null&&chosen().qualification==PhoneIntakeModel.Qualification.CONFIRMED&&!chosen().refused&&draft().status.equals("ELIGIBLE_FOR_PLANNING");boolean phone=false&&selectedReady&&current.report.optBoolean("callPermission")&&current.report.optBoolean("statePermission")&&current.report.optBoolean("numberPermission")&&current.report.optBoolean("idle")&&!current.report.optBoolean("backgroundRestricted");buttons.get("立即受控提交1次").setEnabled(phone&&current.report.optBoolean("dialWindow"));buttons.get("为当前计划授权1次定时通话").setEnabled(phone&&current.report.optBoolean("exactAlarmAllowed")&&!current.report.optBoolean("backgroundRestricted")&&!current.plan.plan.paused&&current.plan.targetId.equals(selected));for(String text:List.of("记录人工已接通并结束","记录未接听","记录结果未知","明确关闭未知待核对"))buttons.get(text).setEnabled(!busy&&pending()!=null);buttons.get("明确关闭未知待核对").setEnabled(!busy&&pending()!=null&&pending().manualResult.equals("UNKNOWN"));notice.setText(busy?"正在处理……":message);}
 private void submit(String action,Work work){if(busy&&current!=null)return;busy=true;controls();worker.execute(()->{String error="";try{work.run();}catch(Exception e){error=safe(e);message=human(error);}try{publish(action,error);}catch(Exception e){runOnUiThread(()->{busy=true;notice.setText("记录读取失败，已停止。请保留数据检查。");});}});}
 private static JSONObject metricJson(AttemptMetrics.Summary s)throws JSONException{return new JSONObject().put("distinctTargets",s.distinctTargets).put("authorizedAttempts",s.authorizedAttempts).put("apiAccepted",s.apiAccepted).put("pending",s.pending).put("manualNoAnswer",s.manualNoAnswer).put("manualCompleted",s.manualCompleted).put("manualUnknown",s.manualUnknown).put("closedUnknown",s.closedUnknown).put("actualOutgoing",JSONObject.NULL).put("actualConnected",JSONObject.NULL);}
 private void publish(String action,String error)throws Exception{
  Data d=new Data();d.report=PilotPhoneRuntime.snapshot(getApplicationContext());try(PhoneIntakeStore s=PhoneIntakeStore.open(this,DataClass.LOCAL_PHONE_INTAKE)){d.contacts=s.list();d.drafts=s.drafts();d.plan=s.plan();d.attempts=s.pilotAttempts();}try{d.account=PilotPhoneRuntime.selectedAccount(this);}catch(Exception ignored){}
  JSONArray contacts=new JSONArray(),attempts=new JSONArray();for(var c:d.contacts)contacts.put(new JSONObject().put("id",c.id).put("maskedNumber",c.maskedNumber).put("revision",c.revision).put("qualification",c.qualification.name()).put("refused",c.refused));for(var a:d.attempts)attempts.put(new JSONObject().put("id",a.id).put("targetId",a.targetId).put("revision",a.revision).put("planVersion",a.planVersion).put("apiSubmittedConfirmed",a.apiSubmittedConfirmed).put("manualResult",a.manualResult).put("pending",a.pending).put("unknownClosed",a.unknownClosed).put("outgoingConfirmed",JSONObject.NULL).put("connectedConfirmed",JSONObject.NULL));
  var entries=d.attempts.stream().map(PhoneIntakeStore.PilotAttempt::metricEntry).collect(java.util.stream.Collectors.toList());var all=AttemptMetrics.summarize(entries,0,Long.MAX_VALUE);java.time.LocalDate day=java.time.LocalDate.now(java.time.ZoneOffset.ofHours(8));long[] range=AttemptMetrics.beijingDay(day);var today=AttemptMetrics.summarize(entries,range[0],range[1]);d.report.put("metrics",new JSONObject().put("scope","CURRENT_LOCAL_PROFILE_AUTHORIZATION_COHORT").put("date",day.toString()).put("timezone","Asia/Shanghai").put("allTime",metricJson(all)).put("today",metricJson(today)));
  d.report.put("ready",true).put("sessionId",session).put("generation",++generation).put("action",action).put("errorCode",error).put("contacts",contacts).put("attempts",attempts).put("planVersion",d.plan.plan.version).put("planPaused",d.plan.plan.paused).put("planStatus",d.plan.status).put("planTargetId",d.plan.targetId).put("dueAt",d.plan.plan.dueAt);
  AtomicFile f=new AtomicFile(new File(getFilesDir(),"pilot-status.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(d.report.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}
  runOnUiThread(()->{if(isDestroyed())return;current=d;busy=false;List<String> labels=new ArrayList<>();int index=0;for(int i=0;i<d.contacts.size();i++){var c=d.contacts.get(i);labels.add(c.maskedNumber+" · "+(c.refused?"拒绝联系":c.qualification==PhoneIntakeModel.Qualification.CONFIRMED?"资格已声明":"资格未确认/撤回"));if(c.id.equals(selected))index=i;}if(!d.contacts.isEmpty())selected=d.contacts.get(index).id;else selected="";rendering=true;targets.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));if(!labels.isEmpty())targets.setSelection(index,false);rendering=false;summary.setText("此页仅用于SIM、权限与旧历史检查。真实外呼请使用企业账号与自动队列。\n销售SIM："+(d.account==null?"尚未绑定":d.account.label+" · "+d.account.maskedNumber)+"\n计划版本 "+d.plan.plan.version+" · "+(d.plan.plan.paused?"暂停":SyntheticWorkspaceModel.formatTime(d.plan.plan.dueAt)+" 北京时间 · "+d.plan.status)+"\n本机累计：不同目标 "+all.distinctTargets+" · 授权尝试 "+all.authorizedAttempts+" · 系统接受请求 "+all.apiAccepted+" · 待核对 "+all.pending+"\n人工未接 "+all.manualNoAnswer+" · 人工完成 "+all.manualCompleted+" · 人工未知 "+all.manualUnknown+"（已明确关闭 "+all.closedUnknown+"）"+"\n今日（北京时间授权日期）：不同目标 "+today.distinctTargets+" · 授权尝试 "+today.authorizedAttempts+"\n实际呼出/接通：未取证"+"\n本次定时许可："+(d.report.optBoolean("armed")?"已授权一次":"未启用")+"；响铃/接通仍需实际核对。");controls();});
 }
 private void selectAccount(){worker.execute(()->{try{List<PilotPhoneRuntime.Account> rows=PilotPhoneRuntime.accounts(this);runOnUiThread(()->new AlertDialog.Builder(this).setTitle("选择销售SIM；切换会暂停旧计划").setItems(rows.stream().map(a->a.label+" · "+a.maskedNumber).toArray(String[]::new),(dialog,n)->submit("SIM",()->{PilotPhoneRuntime.select(getApplicationContext(),rows.get(n));message="SIM已绑定，请重新安排计划。";})).setNegativeButton("取消",null).show());}catch(Exception e){runOnUiThread(()->{message=human(safe(e));controls();});}});}
 private void confirm(boolean automatic){Data seen=current;var c=chosen();var d=draft();if(seen==null||c==null||d==null||seen.account==null)return;String body=c.maskedNumber+"\n销售SIM："+seen.account.label+" · "+seen.account.maskedNumber+"\n仅1次；"+(automatic?SyntheticWorkspaceModel.formatTime(seen.plan.plan.dueAt)+" 北京时间到时自动提交。":"现在立即提交。")+"\n请确认对方同意这次受控联系。";new AlertDialog.Builder(this).setTitle(automatic?"授权一次定时通话":"授权立即通话一次").setMessage(body).setNegativeButton("取消",null).setPositiveButton("确认授权1次",(dialog,n)->submit(automatic?"ARM":"IMMEDIATE",()->{if(automatic){PilotPhoneRuntime.arm(getApplicationContext(),c.id,seen.plan.plan.version,c.revision,d.draft.contactRevision,seen.account.key);message="已授权当前计划一次；暂停或重新安排可停止新外呼。";}else{String status=PilotPhoneRuntime.immediate(getApplicationContext(),c.id,seen.plan.plan.version,c.revision,d.draft.contactRevision,seen.account.key);message=status.equals("API_SUBMITTED")?"电话系统已接收请求；请在结束后核对结果。":"未确认提交或需要核对；不会自动重试。";}})).show();}
 private void result(String result,boolean close){var a=pending();if(a==null)return;Runnable save=()->submit(close?"CLOSE_UNKNOWN":"RESULT",()->{PilotPhoneRuntime.result(getApplicationContext(),a.id,a.revision,result,close);message=close?"已明确关闭；原结果仍未知，不会重放。":"已保存人工记录；下一次需要重新安排或明确触发。";});if(close)new AlertDialog.Builder(this).setTitle("明确关闭未知待核对").setMessage("请确认电话系统没有仍在拨出的通话或待处理请求。关闭后保留未知，不自动重拨。").setNegativeButton("取消",null).setPositiveButton("确认无活动或待处理请求",(dialog,n)->save.run()).show();else save.run();}
 private static String safe(Exception e){String code=e.getMessage();return code!=null&&code.matches("[A-Z_0-9]{1,80}")?code:"PILOT_OPERATION_FAILED";}
 private static String human(String code){switch(code){case "PHONE_PERMISSION_REQUIRED":return "请先授予本应用的手机验证权限；未授权通话。";case "SALES_SIM_REQUIRED":case "SALES_SIM_UNAVAILABLE":return "请明确选择当前可用的销售SIM，不会自动换卡。";case "DEVICE_BUSY":case "DEVICE_NOT_IDLE":return "手机仍占线或状态无法确认，请结束后刷新；请求未排队。";case "OUTSIDE_WINDOW":return "当前不在工作日北京时间09:00至18:00，不会外呼。";case "PENDING_RECONCILIATION":return "请先核对上一条未知结果，不会创建新尝试。";case "EXACT_ALARM_PERMISSION_REQUIRED":return "请允许本应用设置闹钟和提醒。";case "BACKGROUND_RESTRICTED":return "后台运行受限，请检查本应用电池设置后重新安排。";case "FUTURE_PLAN_REQUIRED":return "请先在名单中明确安排未来工作时间的计划。";default:return "操作未完成，请刷新核对计划、资格、SIM和权限；不会自动重试。";}}
 @Override protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
